CREATE TABLE assistance_requests(tenant_id uuid NOT NULL,id uuid NOT NULL,artwork_id uuid NOT NULL,source_revision integer NOT NULL,source_text text NOT NULL CHECK(length(source_text)<=16384),request jsonb NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,artwork_id,source_revision) REFERENCES artwork_revisions(tenant_id,artwork_id,revision));
CREATE TABLE assistance_proposals(tenant_id uuid NOT NULL,id uuid NOT NULL,request_id uuid NOT NULL,content jsonb NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,id),FOREIGN KEY(tenant_id,request_id) REFERENCES assistance_requests(tenant_id,id));
CREATE TABLE assistance_reviews(tenant_id uuid NOT NULL,proposal_id uuid NOT NULL,decision text NOT NULL CHECK(decision IN ('accepted','rejected')),actor_user_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,proposal_id),FOREIGN KEY(tenant_id,proposal_id) REFERENCES assistance_proposals(tenant_id,id));
CREATE TABLE assistance_applications(tenant_id uuid NOT NULL,proposal_id uuid NOT NULL,result_revision integer NOT NULL,actor_user_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,proposal_id),FOREIGN KEY(tenant_id,proposal_id) REFERENCES assistance_proposals(tenant_id,id));
CREATE TRIGGER assistance_requests_immutable BEFORE UPDATE OR DELETE ON assistance_requests FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TRIGGER assistance_proposals_immutable BEFORE UPDATE OR DELETE ON assistance_proposals FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TRIGGER assistance_reviews_immutable BEFORE UPDATE OR DELETE ON assistance_reviews FOR EACH ROW EXECUTE FUNCTION immutable_revision();
CREATE TRIGGER assistance_applications_immutable BEFORE UPDATE OR DELETE ON assistance_applications FOR EACH ROW EXECUTE FUNCTION immutable_revision();
